import socket
import tkinter as tk
from tkinter import scrolledtext
import ttkbootstrap as tb
from ttkbootstrap.constants import *
import base64
from PIL import Image, ImageTk
import io

def on_scan():
    ip = entry_ip.get()
    start = int(entry_start.get())
    end = int(entry_end.get())
    
    result_text.insert(tk.END, f"Scanning {ip} ports {start}-{end}\n")
    result_text.see(tk.END)
    
    for port in range(start, end + 1):
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(0.5)
        result = sock.connect_ex((ip, port))
        if result == 0:
            result_text.insert(tk.END, f"Port {port} open\n")
            result_text.see(tk.END)
        sock.close()
    
    result_text.insert(tk.END, "Scan finished.\n")
    result_text.see(tk.END)

root = tb.Window(themename="darkly")
root.title("Port Scanner 0.1")
root.geometry("800x600")

# Основная сетка
root.grid_rowconfigure(0, weight=1)
root.grid_columnconfigure(0, weight=0)
root.grid_columnconfigure(1, weight=1)

# Левая панель (верхняя часть)
left_frame = tb.Frame(root)
left_frame.grid(row=0, column=0, padx=20, pady=20, sticky="n")

tb.Label(left_frame, text="IP Address:", font=("Consolas", 12)).pack(anchor="w", pady=(0, 5))
entry_ip = tb.Entry(left_frame, font=("Consolas", 12), width=30)
entry_ip.pack(pady=(0, 15))

tb.Label(left_frame, text="Start port:", font=("Consolas", 12)).pack(anchor="w", pady=(0, 5))
entry_start = tb.Entry(left_frame, font=("Consolas", 12), width=30)
entry_start.pack(pady=(0, 15))

tb.Label(left_frame, text="End port:", font=("Consolas", 12)).pack(anchor="w", pady=(0, 5))
entry_end = tb.Entry(left_frame, font=("Consolas", 12), width=30)
entry_end.pack(pady=(0, 15))

tb.Button(left_frame, text="SCAN", command=on_scan, bootstyle="success", width=20).pack(pady=20)

# Логотип в левом нижнем углу - теперь с контролем размера!
logo_frame = tb.Frame(root)
logo_frame.grid(row=1, column=0, padx=80, pady=(0,20), sticky="sw")

# ТВОЙ BASE64 ЛОГОТИП (1254x1254 — сжимаем до 64x64 или 128x128)
base64_logo = """
"""

# Декодируем и РЕСАЙЗИМ до разумных размеров
try:
    logo_data = base64.b64decode(base64_logo.strip())
    logo_image = Image.open(io.BytesIO(logo_data))
    
    # 🔥 КЛЮЧЕВОЙ МОМЕНТ: ресайз до 64x64 (или 100x100, если хочешь чуть крупнее)
    logo_size = (230, 230)  # поменяй на (100,100) если надо побольше
    logo_image.thumbnail(logo_size, Image.Resampling.LANCZOS)
    
    logo_photo = ImageTk.PhotoImage(logo_image)
    logo_label = tb.Label(logo_frame, image=logo_photo)
    logo_label.image = logo_photo  # keep reference
    logo_label.pack()
except Exception as e:
    tb.Label(logo_frame, text="[LOGO]", font=("Consolas", 10), bootstyle="danger").pack()

# Правая область с результатами
result_text = scrolledtext.ScrolledText(root, height=20, font=("Consolas", 10))
result_text.grid(row=0, column=1, rowspan=2, padx=10, pady=10, sticky="nsew")

root.grid_columnconfigure(1, weight=1)
root.grid_rowconfigure(0, weight=1)

root.mainloop()
